import { MeshBasicNodeMaterial } from 'three/webgpu';
import {
  uv,
  vec2,
  color,
  mix,
  fract,
  sin,
  dot,
  smoothstep,
} from 'three/tsl';
import { gsap } from 'gsap';

const COLORS = {
  ink: '#16161d',
  paper: '#e8ecf2',
  accent: '#ff2a38',
  surface: '#0b0b10',
};

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const palette = config?.intent?.visualSpec?.colors ?? COLORS;

  const root = new THREE.Group();
  root.name = 'journal-card-1';
  const inner = new THREE.Group();
  root.add(inner);

  const disposables = [];

  // --- Contact shadow (grounds the card against the stage) ---
  const shadowGeo = new THREE.CircleGeometry(1.5, 32);
  const shadowUv = uv();
  const shadowDist = shadowUv.sub(vec2(0.5, 0.5)).length();
  const shadowAlpha = smoothstep(0.5, 0.0, shadowDist).mul(0.45);
  const shadowMat = new MeshBasicNodeMaterial({ transparent: true });
  shadowMat.colorNode = color(palette.surface);
  shadowMat.opacityNode = shadowAlpha;
  shadowMat.depthWrite = false;
  const shadowMesh = new THREE.Mesh(shadowGeo, shadowMat);
  shadowMesh.position.set(0, -0.08, -0.07);
  inner.add(shadowMesh);
  disposables.push(shadowGeo, shadowMat);

  // --- Accent frame (thin border, kept under 10% of frame area) ---
  const frameGeo = new THREE.PlaneGeometry(2.06, 1.36);
  const frameMat = new MeshBasicNodeMaterial();
  frameMat.colorNode = color(palette.accent);
  const frameMesh = new THREE.Mesh(frameGeo, frameMat);
  frameMesh.position.set(0, 0, -0.03);
  inner.add(frameMesh);
  disposables.push(frameGeo, frameMat);

  // --- Ink backing plate ---
  const backingGeo = new THREE.PlaneGeometry(2.0, 1.3);
  const backingMat = new MeshBasicNodeMaterial();
  backingMat.colorNode = color(palette.ink);
  const backingMesh = new THREE.Mesh(backingGeo, backingMat);
  backingMesh.position.set(0, 0, -0.02);
  inner.add(backingMesh);
  disposables.push(backingGeo, backingMat);

  // --- Image plane: engineered gradient surface + subtle grain ---
  const placeholderTex = new THREE.Texture();
  const imgUv = uv();

  // procedural static grain (no time dependency -> stays static)
  const grainSeed = dot(imgUv, vec2(12.9898, 78.233));
  const grainNoise = fract(sin(grainSeed).mul(43758.5453));
  const grain = grainNoise.sub(0.5).mul(0.05);

  // subtle vignette to keep composition graded, edges recede toward ink
  const vignetteDist = imgUv.sub(vec2(0.5, 0.5)).length();
  const vignette = smoothstep(0.85, 0.35, vignetteDist).mul(0.3).add(0.7);

  const texNode = { current: null };
  const imageMat = new MeshBasicNodeMaterial();

  // build node graph referencing a texture-sample node created via three/tsl `texture`
  // (imported lazily below through dynamic node so we can swap the underlying Texture)
  const buildColorNode = (texture) => {
    const sampled = texture.rgb;
    const graded = sampled.mul(vignette);
    return graded.add(grain);
  };

  // initial: gradient-only surface until the image resolves
  const fallbackGradient = mix(color(palette.ink), color(palette.paper), imgUv.y).mul(vignette).add(grain);
  imageMat.colorNode = fallbackGradient;

  const imageGeo = new THREE.PlaneGeometry(1.86, 1.16);
  const imageMesh = new THREE.Mesh(imageGeo, imageMat);
  imageMesh.position.set(0, 0, 0);
  inner.add(imageMesh);
  disposables.push(imageGeo, imageMat, placeholderTex);

  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      if (!tex) return;
      // rebuild colorNode now that we have the real texture, using the same TSL uv() sampling
      const texSample = tex;
      import('three/tsl').then(({ texture: textureNode }) => {
        const sampled = textureNode(texSample, imgUv);
        imageMat.colorNode = buildColorNode(sampled);
        imageMat.needsUpdate = true;
      });
    }).catch(() => {});
  }

  // --- Entrance motion: weighted settle, translate <=0.4 units ---
  inner.scale.set(0.95, 0.95, 0.95);
  inner.position.set(0, -0.12, 0);
  const tl = gsap.timeline();
  tl.to(inner.position, { y: 0, duration: 0.7, ease: 'power3.out' });
  tl.to(inner.scale, { x: 1.0, y: 1.0, z: 1.0, duration: 0.9, ease: 'power4.out' }, 0);

  root.userData.handlers = {};

  root.userData.cleanup = () => {
    tl.kill();
    disposables.forEach((d) => {
      if (d && typeof d.dispose === 'function') d.dispose();
    });
    if (imageMat.map) {
      imageMat.map.dispose?.();
    }
  };

  return root;
}
